def transform(grid):
 h,w=len(grid),len(grid[0]); out=[row[:] for row in grid]
 # template is upper horizontal run, extend vertical ray from its ends, all until last marked occurrence
 # each distinct color: vertical continuation columns that have first row run, extend where other scattered same color markers define span
 colors=set(v for row in grid for v in row)
 bg=max(colors,key=lambda v:sum(row.count(v) for row in grid))
 for color in colors-{bg}:
  pts=[(r,c) for r in range(h) for c in range(w) if grid[r][c]==color]
  # identify longest horizontal line as source pattern; project its occupied columns down to other same-color marker envelope
  runs=[]
  for r in range(h):
   cs=[c for rr,c in pts if rr==r]
   if len(cs)>=3:runs.append((len(cs),r,cs))
  if not runs:continue
  _,r0,cols=max(runs)
  later=[r for r,c in pts if r>r0]
  if not later:continue
  end=max(later)
  for c in cols:
   for r in range(r0+1,end+1):
    if grid[r][c]==bg:out[r][c]=2
  # complete patterned bottom run only at cells between existing marks? handled other direction
 return out

def transform(grid):
    # Overlay the four panels, using the fixed precedence 9 > 4 > 8 > 5.
    panels = [[row[start:start + 4] for row in grid] for start in (0, 5, 10, 15)]
    priority = (9, 4, 8, 5)
    return [[next((color for color in priority if any(p[r][c] == color for p in panels)), 0)
             for c in range(4)] for r in range(4)]

